import type { Register } from 'claude-code'

export const register: Register = on => {
  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const command = String(e.command)
    if (command.includes('MOD_DENY')) return { deny: 'cd-mod: denied by the tool.call hook' }
    if (command.includes('MOD_REWRITE')) return next({ ...e, command: 'echo rewritten-by-mod' })
    return next(e)
  })
}

